<?php
namespace App\Services\Merit;
use App\Models\MeritFinalizationRun;use App\Models\MeritProcessingRun;use App\Models\MeritProcessingState;use App\Models\MeritResult;use App\Models\User;use Illuminate\Support\Facades\DB;use Illuminate\Validation\ValidationException;
final class MeritFinalizationService
{
 public function __construct(private readonly MeritReadinessService $readiness,private readonly MeritSourceSnapshotComparator $snapshots,private readonly MeritDatasetHasher $hasher,private readonly MeritAuditService $audit){}
 public function finalize(User $actor,string $confirmation,?string $notes=null):MeritFinalizationRun
 {
  if($confirmation!=='FINALIZE')throw ValidationException::withMessages(['confirmation'=>'Type FINALIZE exactly to confirm Merit Generation.']);
  return DB::connection('exam')->transaction(function()use($actor,$notes){$state=MeritProcessingState::query()->lockForUpdate()->firstOrCreate(['id'=>1],['status'=>'not_started']);if($state->is_stale)throw ValidationException::withMessages(['merit'=>'Merit is stale. Regenerate before finalization.']);$run=MeritProcessingRun::query()->lockForUpdate()->whereKey($state->latest_run_id)->first();if(!$run||$run->status!=='completed')throw ValidationException::withMessages(['merit'=>'Complete Merit Generation before finalization.']);$ready=$this->readiness->assertReady();if(!$this->snapshots->equivalent($run->source_snapshot,$ready['source_snapshot']))throw ValidationException::withMessages(['merit'=>'MERIT_SOURCE_HASH_SNAPSHOT_CHANGED: Upstream finalized datasets changed. Regenerate Merit.']);$count=MeritResult::query()->where('processing_run_id',$run->id)->count();if($count!==(int)$run->processed_rows)throw ValidationException::withMessages(['merit'=>'MERIT_RESULT_COUNT_MISMATCH']);$hash=$this->hasher->hash($run->id);if(!$run->dataset_hash||!hash_equals((string)$run->dataset_hash,$hash))throw ValidationException::withMessages(['merit'=>'MERIT_DATASET_HASH_MISMATCH: Generated Merit data changed before finalization.']);MeritFinalizationRun::query()->where('status','current')->update(['status'=>'superseded']);$summary=array_merge((array)$run->summary,['dataset_hash'=>$hash,'finalized_at'=>now()->toIso8601String()]);$final=MeritFinalizationRun::query()->create(['processing_run_id'=>$run->id,'processing_version'=>$run->processing_version,'status'=>'current','source_snapshot'=>$run->source_snapshot,'dataset_hash'=>$hash,'summary'=>$summary,'finalized_by'=>$actor->id,'finalized_at'=>now(),'notes'=>$notes]);$before=$state->status;$state->update(['status'=>'finalized','latest_finalization_run_id'=>$final->id,'dataset_hash'=>$hash,'summary'=>$summary,'finalized_by'=>$actor->id,'finalized_at'=>now(),'is_stale'=>false,'stale_reason'=>null]);$this->audit->record('MERIT_FINALIZED',$actor,$before,'finalized',summary:$summary,runId:$run->id);return $final;},3);
 }
}
